import re

UNIT_SECONDS = {
    's': 1, 'sec': 1, 'secs': 1, 'second': 1, 'seconds': 1,
    'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60,
    'h': 3600, 'hr': 3600, 'hrs': 3600, 'hour': 3600, 'hours': 3600,
    'd': 86400, 'day': 86400, 'days': 86400,
    'w': 604800, 'wk': 604800, 'wks': 604800, 'week': 604800, 'weeks': 604800,
}

_ISO_RE = re.compile(
    r'P'
    r'(?:(\d+(?:\.\d+)?)W)?'
    r'(?:(\d+(?:\.\d+)?)D)?'
    r'(?:T'
    r'(?:(\d+(?:\.\d+)?)H)?'
    r'(?:(\d+(?:\.\d+)?)M)?'
    r'(?:(\d+(?:\.\d+)?)S)?'
    r')?'
)

_COMPONENT_RE = re.compile(r'(\d+(?:\.\d+)?)\s*([a-zA-Z]+)')


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if text is None:
        raise ValueError("duration must be a string")

    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    # bare non-negative integer
    if re.fullmatch(r'\d+', s):
        return int(s)

    # clock notation hh:mm:ss
    m = re.fullmatch(r'(\d+):(\d+):(\d+)', s)
    if m:
        h, mi, se = (int(x) for x in m.groups())
        return h * 3600 + mi * 60 + se

    # clock notation mm:ss
    m = re.fullmatch(r'(\d+):(\d+)', s)
    if m:
        mi, se = (int(x) for x in m.groups())
        return mi * 60 + se

    # ISO 8601 duration
    m = _ISO_RE.fullmatch(s)
    if m and any(m.groups()):
        w, d, h, mi, se = m.groups()
        total = 0.0
        if w:
            total += float(w) * UNIT_SECONDS['w']
        if d:
            total += float(d) * UNIT_SECONDS['d']
        if h:
            total += float(h) * UNIT_SECONDS['h']
        if mi:
            total += float(mi) * UNIT_SECONDS['m']
        if se:
            total += float(se) * UNIT_SECONDS['s']
        return round(total)

    # general "number unit" sequences, optionally space separated
    pos = 0
    total = 0.0
    found_any = False
    length = len(s)
    for match in _COMPONENT_RE.finditer(s):
        if match.start() != pos:
            raise ValueError(f"could not parse duration: {text!r}")
        pos = match.end()
        num = float(match.group(1))
        unit = match.group(2).lower()
        if unit not in UNIT_SECONDS:
            raise ValueError(f"unknown unit: {unit}")
        total += num * UNIT_SECONDS[unit]
        found_any = True
        while pos < length and s[pos] == ' ':
            pos += 1

    if not found_any or pos != length:
        raise ValueError(f"could not parse duration: {text!r}")

    return round(total)

